rdf.8:
ex:skole
    a skos:Concept ;
    dcat:contactPoint kontakt:begrepsforvaltning ;
    dcterms:identifier "https://example.org/begrep/skole"^^xsd:anyURI ;
    dcterms:publisher virksomhet:modellforvalter ;
    skos:broader ex:organisasjon ;
    skos:definition "organisasjon som tilbyr organisert opplæring til elever"@nb ;
    skos:inScheme system:skole ;
    skos:prefLabel "skole"@nb ,
        "skule"@nn ;
    skosno:isFromConceptIn [
        a skosno:AssociativeConceptRelation ;
        skosno:hasToConcept ex:organisasjon ;
        skosno:relationRole "har skoleeier"@nb ,
            "har skuleeigar"@nn
    ] ;
    xkos:generalizes ex:videregåendeskole ,
        ex:ungdomsskole ;
    xkos:specializes ex:organisasjon .

rdf.9:
ex:person
    a skos:Concept ;
    dcat:contactPoint kontakt:begrepsforvaltning ;
    dcterms:identifier "https://example.org/begrep/person"^^xsd:anyURI ;
    dcterms:publisher virksomhet:modellforvalter ;
    skos:definition "menneske"@nb ;
    skos:inScheme system:skole ;
    skos:prefLabel "person"@nb ,
        "person"@nn ;
    xkos:generalizes ex:elev .

rdf.13:
samling:skole
    a skos:Collection ;
    dcat:contactPoint kontakt:begrepsforvaltning ;
    dcterms:identifier "https://example.org/begrepssamling/skole"^^xsd:anyURI ;
    dcterms:publisher virksomhet:modellforvalter ;
    dcterms:title "Omgrep i skuledomenet"@nn ,
        "Begreper i skoledomenet"@nb ;
    skos:member ex:fylkeskommune ,
        ex:videregåendeskole ,
        ex:organisasjon ,
        ex:elev ,
        ex:kommune ,
        ex:ungdomsskole ,
        ex:skole ,
        ex:person .

rdf.14:
rule:Person-PersonId
    a sh:PropertyShape ;
    sh:maxCount "1"^^xsd:integer ;
    sh:minCount "1"^^xsd:integer ;
    sh:or ( rule:PersonID-ssn rule:PersonID-dnr rule:PersonID-fictionalId ) ;
    sh:path <http://www.example.com/hasPersonId> .

